import { useAssistant } from '@proton/llm/lib';

import { parseModelResult } from 'proton-mail/helpers/assistant/result';

import './ComposerAssistantResult.scss';

interface Props {
    result: string;
    assistantID: string;
    isComposerPlainText: boolean;
}

const HTMLResult = ({ result }: { result: string }) => {
    const sanitized = parseModelResult(result);
    return <div dangerouslySetInnerHTML={{ __html: sanitized }} className="composer-assistant-result"></div>;
};

const ComposerAssistantResult = ({ result, assistantID, isComposerPlainText }: Props) => {
    const { isGeneratingResult, canKeepFormatting } = useAssistant(assistantID);

    if (isGeneratingResult || isComposerPlainText || !canKeepFormatting) {
        return <div>{result}</div>;
    }
    // We transform and clean the result after generation completed to avoid costly operations (markdown to html, sanitize)
    return <HTMLResult result={result} />;
};

export default ComposerAssistantResult;
import type { MutableRefObject, RefObject } from 'react';
import { useEffect, useMemo, useRef, useState } from 'react';

import type { EditorMetadata } from '@proton/components';
import { useModalStateObject } from '@proton/components';
import ComposerAssistantUpsellModal from '@proton/components/components/upsell/modal/types/ComposerAssistantUpsellModal';
import { ASSISTANT_SERVER_THROTTLE_TIMEOUT, getHasAssistantStatus, useAssistant } from '@proton/llm/lib';
import { OpenedAssistantStatus } from '@proton/llm/lib/types';
import { ERROR_TYPE } from '@proton/shared/lib/assistant';
import { wait } from '@proton/shared/lib/helpers/promise';
import type { Recipient } from '@proton/shared/lib/interfaces';
import clsx from '@proton/utils/clsx';

import ComposerAssistantExpanded from 'proton-mail/components/assistant/ComposerAssistantExpanded';
import ResumeDownloadingModal from 'proton-mail/components/assistant/modals/ResumeDownloadingModal';
import ComposerAssistantToolbar from 'proton-mail/components/assistant/toolbar/ComposerAssistantToolbar';
import type { ComposerReturnType } from 'proton-mail/helpers/composer/contentFromComposerMessage';
import { removeLineBreaks } from 'proton-mail/helpers/string';
import useComposerAssistantGenerate from 'proton-mail/hooks/assistant/useComposerAssistantGenerate';
import useComposerAssistantScrollButton from 'proton-mail/hooks/assistant/useComposerAssistantScrollButton';
import useComposerAssistantSelectedText from 'proton-mail/hooks/assistant/useComposerAssistantSelectedText';
import { ComposerInnerModalStates } from 'proton-mail/hooks/composer/useComposerInnerModals';

import './ComposerAssistant.scss';

interface Props {
    assistantID: string;
    editorMetadata: EditorMetadata;
    composerSelectedText: string;
    getContentBeforeBlockquote: (returnType?: ComposerReturnType) => string;
    setContentBeforeBlockquote: (content: string) => void;
    composerContentRef: RefObject<HTMLElement>;
    composerContainerRef: RefObject<HTMLElement>;
    composerMetaRef: RefObject<HTMLElement>;
    onUseRefinedText: (value: string) => void;
    onUseGeneratedText: (value: string) => void;
    setInnerModal: (innerModal: ComposerInnerModalStates) => void;
    recipients: Recipient[];
    sender: Recipient | undefined;
    setAssistantStateRef: MutableRefObject<() => void>;
}

const ComposerAssistant = ({
    assistantID,
    editorMetadata,
    composerSelectedText,
    getContentBeforeBlockquote,
    setContentBeforeBlockquote,
    onUseRefinedText,
    onUseGeneratedText,
    setInnerModal,
    recipients,
    sender,
    setAssistantStateRef,
}: Props) => {
    const [prompt, setPrompt] = useState('');
    const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);

    const assistantResultChildRef = useRef<HTMLDivElement>(null);
    const assistantResultRef = useRef<HTMLDivElement>(null);

    const assistantUpsellModal = useModalStateObject();
    const resumeDownloadModal = useModalStateObject();

    const { openedAssistants, setAssistantStatus, resumeDownloadModel, error, cleanSpecificErrors } =
        useAssistant(assistantID);

    const isAssistantExpanded = useMemo(() => {
        return getHasAssistantStatus(openedAssistants, assistantID, OpenedAssistantStatus.EXPANDED);
    }, [assistantID, openedAssistants]);

    const expandAssistant = () => {
        if (!isAssistantExpanded) {
            setAssistantStatus(assistantID, OpenedAssistantStatus.EXPANDED);
        }
    };

    const { showArrow, handleScrollToBottom, checkScrollButtonDisplay } = useComposerAssistantScrollButton({
        assistantResultChildRef,
        assistantResultRef,
    });

    // Selected text in the composer or assistant result that the user might want to refine
    const { selectedText, handleMouseDown, handleSelectionChange } = useComposerAssistantSelectedText({
        assistantID,
        assistantResultRef,
        composerSelectedText,
        onResetRequest: () => setPrompt(''),
    });

    const {
        generationResult,
        setGenerationResult,
        previousGenerationResult,
        setPreviousGenerationResult,
        generate,
        submittedPrompt,
        replaceMessageBody,
    } = useComposerAssistantGenerate({
        assistantID,
        isComposerPlainText: editorMetadata.isPlainText,
        showAssistantSettingsModal: () => setInnerModal(ComposerInnerModalStates.AssistantSettings),
        showResumeDownloadModal: () => resumeDownloadModal.openModal(true),
        showUpsellModal: () => assistantUpsellModal.openModal(true),
        onResetFeedbackSubmitted: () => {
            setFeedbackSubmitted(false);
        },
        expanded: isAssistantExpanded,
        recipients,
        sender,
        getContentBeforeBlockquote,
        checkScrollButtonDisplay,
        selectedText,
        composerSelectedText,
        onUseGeneratedText,
        onUseRefinedText,
        setContentBeforeBlockquote,
        prompt,
        setPrompt,
        setAssistantStatus,
    });

    const handleResetToPreviousPrompt = () => {
        if (previousGenerationResult) {
            setGenerationResult(previousGenerationResult);
        }
    };

    const handleResetGeneration = () => {
        setGenerationResult('');
        setPreviousGenerationResult('');
    };

    // When user is making a harmful generation on top of a previous generation, reset the content to the previous generation
    useEffect(() => {
        if (error && error.errorType === ERROR_TYPE.GENERATION_HARMFUL) {
            handleResetToPreviousPrompt();
        }
    }, [error]);

    // Set ref content used to reset assistant state when user is using escape shortcut
    useEffect(() => {
        setAssistantStateRef.current = async () => {
            setPrompt('');
            // Wait for the last callback to be called before cleaning the generation
            await wait(ASSISTANT_SERVER_THROTTLE_TIMEOUT + 20);
            setGenerationResult('');
            setPreviousGenerationResult('');
            cleanSpecificErrors();
        };
    }, [setPrompt, setPreviousGenerationResult]);

    const hasComposerContent = !!removeLineBreaks(getContentBeforeBlockquote());

    // Show refine buttons when:
    // - There is some content selected in the assistant expanded
    // - Message body in composer has some content
    // - There is some content that has been generated in the assistant expanded
    const canUseRefineButtons = !!selectedText || (!isAssistantExpanded && hasComposerContent) || !!generationResult;

    return (
        // eslint-disable-next-line jsx-a11y/no-static-element-interactions
        <div
            className={clsx([
                'composer-assistant-container mt-2 relative flex flex-column flex-nowrap',
                isAssistantExpanded && 'absolute composer-assistant-container--expanded',
            ])}
            onMouseDown={handleMouseDown}
        >
            <ComposerAssistantToolbar
                assistantID={assistantID}
                prompt={prompt}
                setPrompt={setPrompt}
                selectedText={selectedText}
                isAssistantExpanded={isAssistantExpanded}
                onExpandAssistant={expandAssistant}
                onGenerate={generate}
                canUseRefineButtons={canUseRefineButtons}
                onCancelGeneration={handleResetToPreviousPrompt}
            />

            {isAssistantExpanded && (
                <ComposerAssistantExpanded
                    assistantID={assistantID}
                    isComposerPlainText={editorMetadata.isPlainText}
                    generationResult={generationResult}
                    assistantResultChildRef={assistantResultChildRef}
                    assistantResultRef={assistantResultRef}
                    onSelectionChange={handleSelectionChange}
                    checkScrollButtonDisplay={checkScrollButtonDisplay}
                    showArrow={showArrow}
                    onScrollToBottom={handleScrollToBottom}
                    replaceMessageBody={replaceMessageBody}
                    submittedPrompt={submittedPrompt}
                    feedbackSubmitted={feedbackSubmitted}
                    setFeedbackSubmitted={setFeedbackSubmitted}
                    onResetPrompt={() => setPrompt('')}
                    onResetGeneration={handleResetGeneration}
                    showReplaceButton={hasComposerContent}
                />
            )}

            {assistantUpsellModal.render && (
                <ComposerAssistantUpsellModal modalProps={assistantUpsellModal.modalProps} />
            )}
            {resumeDownloadModal.render && (
                <ResumeDownloadingModal
                    modalProps={{
                        ...resumeDownloadModal.modalProps,
                    }}
                    onResumeDownload={() => resumeDownloadModel?.()}
                />
            )}
        </div>
    );
};

export default ComposerAssistant;
import { DEFAULT_FONT_FACE_ID, DEFAULT_FONT_SIZE } from '@proton/components/components/editor/constants';
import { checkContrast, parseStringToDOM } from '@proton/shared/lib/helpers/dom';
import type { Address, MailSettings, UserSettings } from '@proton/shared/lib/interfaces';
import type { Message } from '@proton/shared/lib/interfaces/mail/Message';
import { isPlainText, isPlainText as testIsPlainText } from '@proton/shared/lib/mail/messages';
import { message } from '@proton/shared/lib/sanitize';
import { escape, unescape } from '@proton/shared/lib/sanitize/escape';

import { MESSAGE_IFRAME_ROOT_ID } from '../../components/message/constants';
import type { MESSAGE_ACTIONS } from '../../constants';
import type { MessageState, PartialMessageState } from '../../store/messages/messagesTypes';
import { parseModelResult } from '../assistant/result';
import { findSender } from '../message/messageRecipients';
import { toText } from '../parserHtml';
import { textToHtml } from '../textToHtml';
import { locateBlockquote } from './messageBlockquote';
import { generateBlockquote } from './messageDraft';

export const getPlainTextContent = (message: PartialMessageState) => {
    return message.messageDocument?.plainText || '';
};

export const getDocumentContent = (document: Element | undefined) => {
    const root = document?.querySelector('body') || document;
    return root?.innerHTML || '';
};

/**
 * Get current processed message document html content
 */
export const getContent = (message: PartialMessageState) => {
    if (testIsPlainText(message.data)) {
        return getPlainTextContent(message);
    }

    return getDocumentContent(message.messageDocument?.document);
};

export const setPlainTextContent = (message: MessageState, content: string) => {
    if (message.messageDocument) {
        message.messageDocument.plainText = content;
    } else {
        message.messageDocument = { plainText: content };
    }
};

export const setDocumentContent = (document: Element | undefined, content: string) => {
    if (document) {
        document.innerHTML = content;
    } else {
        document = parseStringToDOM(content).body;
    }

    return document;
};

/**
 * Set current processed message document html
 */
export const setContent = (message: MessageState, content: string) => {
    if (testIsPlainText(message.data)) {
        setPlainTextContent(message, content);
    } else {
        const document = setDocumentContent(message.messageDocument?.document, content);
        if (message.messageDocument) {
            message.messageDocument.document = document;
        } else {
            message.messageDocument = { document };
        }
    }
};

export const exportPlainText = (content: string) => {
    /*
     * The replace removes any characters that are produced by the copying process (like zero width characters)
     * See: http://www.berklix.org/help/majordomo/#quoted we want to avoid sending unnecessary quoted printable encodings
     */
    return toText(content).replace(/\u200B/g, '');
};

/**
 * Generates/Gets the plaintext body from the message. If the message is not composed in plaintext, it will downconvert
 * the html body to plaintext if downconvert is set. If downconvert is disabled it will return false.
 */
export const getPlainText = (message: MessageState, downconvert: boolean) => {
    if (testIsPlainText(message.data)) {
        return getPlainTextContent(message);
    }

    if (!downconvert) {
        return undefined;
    }

    return exportPlainText(getContent(message));
};

/**
 * Convert the body of a message in plain text to an HTML version
 */
export const plainTextToHTML = (
    message: Partial<Message> | undefined,
    plainTextContent: string | undefined,
    mailSettings: MailSettings | undefined,
    userSettings: UserSettings | undefined,
    addresses: Address[]
) => {
    const sender = findSender(addresses, message);
    return textToHtml(plainTextContent, sender?.Signature || '', mailSettings, userSettings);
};

export const querySelectorAll = (message: Partial<MessageState> | undefined, selector: string) => [
    ...((message?.messageDocument?.document?.querySelectorAll(selector) || []) as HTMLElement[]),
];

export const canSupportDarkStyle = (iframe: HTMLIFrameElement | null) => {
    const container = iframe?.contentDocument?.getElementById(MESSAGE_IFRAME_ROOT_ID);
    const window = iframe?.contentWindow;

    if (!container || !window) {
        return false;
    }

    const colorSchemeMetaTag = container.querySelector('meta[name="color-scheme"]');

    // If the meta tag color-scheme is present, we assume that the email supports dark mode
    if (colorSchemeMetaTag?.getAttribute('content')?.includes('dark')) {
        return true;
    }

    const supportedColorSchemesMetaTag = container.querySelector('meta[name="supported-color-schemes"]');

    // If the meta tag supported-color-schemes is present, we assume that the email supports dark mode
    if (supportedColorSchemesMetaTag?.getAttribute('content')?.includes('dark')) {
        return true;
    }

    const styleTag = container.querySelector('style');
    const styleTextContent = styleTag?.textContent;

    // If the media query prefers-color-scheme is present, we assume that the email supports dark mode
    if (styleTextContent?.includes('color-scheme') || styleTextContent?.includes('prefers-color-scheme')) {
        return true;
    }

    const contrastResult = checkContrast(container, window);

    return contrastResult;
};

export const getContentWithoutBlockquotes = (
    message: MessageState,
    referenceMessage: MessageState,
    mailSettings: MailSettings,
    userSettings: UserSettings,
    addresses: Address[],
    action: MESSAGE_ACTIONS
) => {
    if (testIsPlainText(message.data)) {
        const blockquotes = generateBlockquote(referenceMessage || {}, mailSettings, userSettings, addresses, action);
        const plainBlockquotes = toText(blockquotes);

        return message.messageDocument?.plainText?.replace(plainBlockquotes, '');
    }

    const [contentBeforeBlockquotes] = locateBlockquote(message.messageDocument?.document);

    return contentBeforeBlockquotes;
};

export const getContentWithBlockquotes = (
    content: string,
    isPlainText: boolean,
    referenceMessage: MessageState,
    mailSettings: MailSettings,
    userSettings: UserSettings,
    addresses: Address[],
    action: MESSAGE_ACTIONS
) => {
    const blockquotes = generateBlockquote(referenceMessage || {}, mailSettings, userSettings, addresses, action);

    if (isPlainText) {
        const plainBlockquotes = toText(blockquotes);

        return `${content}${plainBlockquotes}`;
    } else {
        return `${content}${blockquotes.toString()}`;
    }
};

/**
 * @param mailSettings
 * @returns string containing fon styles. to be inserted in `style` attribute of an HTML element
 * @example
 * ```
 * This usage
 * <div style="${getComposerDefaultFontStyles(mailSettings)}">...</div>
 * Becomes
 * <div style="font-family: Arial, serif; font-size: 12px;">...</div>
 * ```
 */
export const getComposerDefaultFontStyles = (mailSettings: MailSettings) =>
    `font-family: ${mailSettings?.FontFace || DEFAULT_FONT_FACE_ID}; font-size: ${mailSettings?.FontSize || DEFAULT_FONT_SIZE}px`;

export const prepareContentToInsert = (textToInsert: string, isPlainText: boolean, isMarkdown: boolean) => {
    if (isPlainText) {
        return unescape(textToInsert);
    }

    if (isMarkdown) {
        return parseModelResult(textToInsert);
    }

    // Because rich text editor convert text to HTML, we need to escape the text before inserting it
    // As a 2nd layer of security, to prevent adding unsafe elements, we also want to sanitize the content before importing it
    const escapedText = escape(textToInsert);
    const sanitizedText = message(escapedText);

    return sanitizedText;
};

export const insertTextBeforeContent = (
    message: MessageState,
    textToInsert: string,
    mailSettings: MailSettings,
    needsSeparator: boolean
) => {
    let newBody;
    // In both cases, add a separator only if there is already some content in the composer
    // However we still need to add message body after because message might contain signature or blockquotes
    if (isPlainText(message.data)) {
        const separator = '--------------------';
        const messageBody = message.messageDocument?.plainText;

        newBody = needsSeparator ? `${textToInsert}\n${separator}\n${messageBody}` : `${textToInsert}\n${messageBody}`;
    } else {
        const separator = `<hr/>`;
        const messageBody = message.messageDocument?.document?.innerHTML;
        const textToInsertHTML = textToInsert.replaceAll('\n', '<br>');
        const fontStyles = getComposerDefaultFontStyles(mailSettings);

        newBody = needsSeparator
            ? `<div style="${fontStyles}">${textToInsertHTML}</div><br>${separator}<br>${messageBody}`
            : `<div style="${fontStyles}">${textToInsertHTML}</div><br>${messageBody}`;
    }
    return newBody;
};

import { forgeImageURL } from '@proton/shared/lib/helpers/image';

import { API_URL } from 'proton-mail/config';

import { ASSISTANT_IMAGE_PREFIX, replaceURLs, restoreURLs } from './url';

const linkUrl = 'https://example.com';
const image1URL = 'https://example.com/image.jpg';
const image2URL = 'https://example.com/image2.jpg';
const image2ProxyURL = 'https://proxy.com/image2.jpg';
const image3URL = 'https://example.com/image3.jpg';

const embeddedImageURL = 'blob:https://example.com/image3.jpg';
const embeddedImageID = 'embedded-id';
const embeddedImageDataEmbedded = 'cid:embedded-img';

const replaceURLsInContent = () => {
    const dom = document.implementation.createHTMLDocument();
    dom.body.innerHTML = `
            <a href="${linkUrl}">Link</a>
            <img src="${image1URL}" alt="Image" />
            <img proton-src="${image2URL}" src="${image2ProxyURL}" alt="Image" />
            <img src="${embeddedImageURL}" alt="Image" class="proton-embedded" id="${embeddedImageID}" data-embedded-img="${embeddedImageDataEmbedded}"/>
            <img proton-src="${image3URL}" alt="Image" class="proton-embedded"/>
        `;

    return replaceURLs(dom, 'uid');
};

describe('replaceURLs', () => {
    it('should replace URLs in links and images by incremental number', () => {
        const newDom = replaceURLsInContent();

        const links = newDom.querySelectorAll('a[href]');
        const images = newDom.querySelectorAll('img[src]');

        expect(links.length).toBe(1);
        expect(links[0].getAttribute('href')).toBe(`${ASSISTANT_IMAGE_PREFIX}0`);
        expect(images.length).toBe(4);
        expect(images[0].getAttribute('src')).toBe(`${ASSISTANT_IMAGE_PREFIX}1`);
        expect(images[1].getAttribute('src')).toBe(`${ASSISTANT_IMAGE_PREFIX}2`);
        expect(images[2].getAttribute('src')).toBe(`${ASSISTANT_IMAGE_PREFIX}3`);
        expect(images[3].getAttribute('src')).toBe(`${ASSISTANT_IMAGE_PREFIX}4`);
    });
});

describe('restoreURLs', () => {
    it('should restore URLs in links and images', () => {
        const dom = replaceURLsInContent();

        const newDom = restoreURLs(dom);

        const links = newDom.querySelectorAll('a[href]');
        const images = newDom.querySelectorAll('img[src]');

        expect(links.length).toBe(1);
        expect(links[0].getAttribute('href')).toBe(linkUrl);

        expect(images.length).toBe(4);

        expect(images[0].getAttribute('src')).toBe(image1URL);

        expect(images[1].getAttribute('src')).toBe(image2ProxyURL);
        expect(images[1].getAttribute('proton-src')).toBe(image2URL);

        // Embedded image
        expect(images[2].getAttribute('src')).toBe(embeddedImageURL);
        expect(images[2].getAttribute('class')).toBe('proton-embedded');
        expect(images[2].getAttribute('data-embedded-img')).toBe(embeddedImageDataEmbedded);
        expect(images[2].getAttribute('id')).toBe(embeddedImageID);

        // Remote to load using proxy
        const expectedProxyURL = forgeImageURL({
            apiUrl: API_URL,
            url: 'https://example.com/image3.jpg',
            uid: 'uid',
            origin: window.location.origin,
        });
        expect(images[3].getAttribute('src')).toBe(expectedProxyURL);
        expect(images[3].getAttribute('proton-src')).toBe(image3URL);
        expect(images[3].getAttribute('class')).toBe('proton-embedded');
